INSERT INTO `songs` (`id`, `title`, `province`, `audio_path`, `lyrics`, `translation`, `cultural_values`, `thumbnail`) VALUES
(1, 'Lalan Belek', 'Bengkulu', 'bengkulu-lalanbelek.wav', 'Oi lalan belek...\r\nOi lalan belek\r\nLalan belek\r\n\r\nOi lalan belek...\r\nOi lalan belek\r\nLalan belek\r\n\r\nKemak boloak si depeak\r\nDepeak nang au\r\n\r\nKemak dawen si lipet duwei\r\nLipet duwei\r\n\r\nKunyeu depoloak etun temegeak nang au\r\nBelek asen ite beduei ite beduei\r\n\r\nOi lalan belek...\r\nOi lalan belek...\r\nLalan belek\r\n\r\nOi lalan belek...\r\nOi lalan belek...\r\nLalan belek\r\n\r\nAmen ku namen repie epet nang au\r\nCoa ku melapen eboak kedulo\r\n\r\nAmen kunamen idup yo peset nang au\r\nCoa ku lak tu\'un mai dunio\r\nTu\'un mai dunio.\r\n\r\nOi lalan belek...\r\nOi lalan belek...\r\nLalan belek\r\n\r\nOi lalan belek...\r\nOi lalan belek...\r\nLalan belek.\r\n\r\nAmen ade seludang pinang nang au\r\nJano guno ku upeak igei\r\n\r\nKu upeak igei.\r\nAmen ade bayang betunang nang au\r\n\r\nJano guno bemedeak igei\r\nBemedeak igei.\r\n\r\nOi lalan belek...\r\nOi lalan belek...\r\nLalan belek\r\n\r\nOi lalan belek...\r\nOi lalan belek...\r\nLalan belek.\r\n\r\nBilei iyo temanem tebeu nang au\r\nMemen sebilei temanem seie\r\n\r\nTemanem seie.\r\nBilei iyo ite betemu nang au\r\nMemen sebilei ite becei\r\n\r\nIte becei.\r\nOi lalan belek...\r\nOi lalan belek...\r\nLalan belek... (3x)', 'Duhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nAmbil bambu sebelah sebelah\r\nAmbil daun dilipat dua lipat dua\r\n\r\nBiar sepuluh orang melarang\r\nKembali rasa kita berdua\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nKalau ku tahu buah pare pahit\r\nTidak ku masak buah kedula\r\n\r\nKalau ku tahu hidup ini sengsara\r\nTidak ku mau turun ke dunia\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nKalau ada pelepah pinang\r\nApa guna ku upah lagi\r\n\r\nKalau ada bayangan hendak bertunangan\r\nApa guna berkata-kata lagi\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nHari ini menanam tebu\r\nBesok lusa menanam serai\r\n\r\nHari ini kita bertemu\r\nBesok lusa kita bercerai\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\n\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah\r\nDuhai Lalan kembalilah', 'Makna Lagu Daerah Suku Rejang Lebong milik Dela Larasati, lagu Lalan Balek berisi ungkapan kerinduan yang dibalut dengan kesedihan. Lagu ini tercipta karena adanya cerita rakyat tentang seorang ibu yang merindukan anaknya.\r\n\r\nIbu menunggu anaknya datang dengan merintih menyebutkan nama \"Lalan\". Bait pertama dari lagu tersebut merupakan isi kesedihan seorang ibu yang menunggu kepulangan anaknya pulang ke rumah.', 'images/thumb-bengkulu1.jpg'),
(2, 'Anak Kunang', 'Bengkulu', 'bengkulu-AnakKunang.wav', 'Ko laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang\r\n\r\nTebo leceak be pagar pinang\r\nTebo dawen be deret bae\r\n\r\nApi madeak gicolak senang\r\nCuma babagei tenimo bae\r\n\r\nKo laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang\r\n\r\nKarang tinggei nak lubuk tabah\r\nDalen belek kak tabeak penanjung\r\n\r\nAmen cigei indok ngen bapak\r\nAwei ba kacang gi pateak junjung\r\n\r\nKo laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang\r\n\r\nKeleak doo si burung ponoi\r\nMesoa umpan nak padang lalang\r\nLueng kelmen uku menginoe\r\nSemesoa bagei gituun malang\r\n\r\nKo laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang\r\n\r\nAsen tuein cao menoo\r\nCao uyo leyen igei\r\nTengen igei lak murus tuntuei\r\nKaleu coa uyo tengen ba igei\r\n\r\nKo laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang\r\nKo laleu dete asoak sayang ku tingga suang', 'Lihat itu si burung ponoi Mencari makan di padang ilalang Pagi malam saya menangis Menyesal nasib yang turun malang\r\n\r\nKamu pergi duluan adek sayang, saya tinggal seorang (4x)\r\n\r\nBukit basa batas pinang Bukit daun berbaris saja Siapa bilang tak mau senang Karena nasib terima saja\r\n\r\nKamu pergi duluan adek sayang, saya tinggal seorang (2x)\r\n\r\nJalan balik lewat Tabah Penanjung Kalau tidak ada ibu dan bapak Bagaikan kacang patah tongkatnya Kamu pergi duluan adek sayang, tinggal seorang\r\n\r\nPianang lamaran orang dulu Orang kini beda lagi Kamu pergi duluan adik sayang, ku tinggal seorang (2x)\r\n\r\nKapan lagi mau merawat orang tua Kalau tidak kini kapan lagi\r\n\r\nKamu pergi duluan adek sayang, saya tinggal seorang (4x)', 'Lagu Anak Kunang memiliki arti mendalam tentang perasaan rela seorang kakak yang mempersilahkan adik kandungnya menikah lebih dulu. Lagu ini memuat tentang kebudayaan dan tradisi yang ada di suku Rejang, Bengkulu.\r\n\r\nlagu Anak Kunang dianggap sebagai cerita seorang anak yang merindukan kampung halaman. Anak tersebut mengenang masa kecilnya yang begitu bahagia saat tinggal di Bengkulu. Ia bermain di kebun kelapa dan mendengarkan cerita dongeng dari bapaknya.\r\n\r\nNamun sayang, kehidupannya sekarang jauh dari kampung halaman. Melalui lagu ini, ia menyampaikan perasaan kerinduan terhadap kenangan masa lalu di desanya.', 'images/thumb-bengkulu2.jpg'),
(3, 'Yo Botoi Botoi', 'Bengkulu', 'bengkulu-Botoi.wav', 'Yo botoi-botoi yo tarik tali\r\n\r\nElok-elok pukek besamo\r\n\r\nPukeklah mendarek\r\n\r\nMarolah kito seiyo\r\n\r\nYo botoi-botoi yo tarik tali\r\n\r\nElok-elok pukek besamo\r\n\r\nSelengek yang di dapek\r\n\r\nBanyaknyo bakerang-kerang...\r\n\r\nUncu leha… (Uncu Leha)\r\n\r\nMenunggu pak uncu di rumah… (di rumah)\r\n\r\nAir kopi kek juada lah lamo lah tesedio ho...ho…\r\n\r\nUncu leha… (Uncu Leha)\r\n\r\nMenunggu pak uncu di rumah…. (di rumah)\r\n\r\nAir kopi kek juada lah lamo lah tesedio', 'Yo botoi-botoi, ayo tarik tali\r\n\r\nCantik-cantik main bersama\r\n\r\nTarik-tarikanlah\r\n\r\nMari kita bersenang-senang\r\n\r\nYo botoi-botoi, ayo tarik tali\r\n\r\nCantik-cantik main bersama\r\n\r\nSelengek yang didapat\r\n\r\nBanyak sekali kerang-kerangnya...\r\n\r\nUncu Leha…\r\n\r\nMenunggu pak uncu di rumah…\r\n\r\nAir kopi sudah lama, sudah siap ho...ho…\r\n\r\nUncu Leha…\r\n\r\nMenunggu pak uncu di rumah…\r\n\r\nAir kopi sudah lama, sudah siap', 'Lagu ini menceritakan tentang kisah seseorang atau sekelompok nelayan, yang sedang menangkap ataupun mencari ikan di laut menggunakan pukek.\r\n\r\nPukek adalah alat penangkap ikan yang telah berumur lama, bahkan telah digunakan sejak zaman dahulu.\r\n\r\nLagu ini biasa dinyanyikan saat ada acara atau saat pagelaran seni.\r\n\r\nDikenal dengan melodi yang riang dan lirik yang menggambarkan kehidupan sehari-hari.', 'images/thumb-bengkulu3.jpg'),
(4, 'Lir Ilir', 'Jawa Tengah', 'jateng-Lir.wav', 'Lir ilir, lir ilir Tandure wis sumilir Tak ijo royo-royo, tak sengga temanten anyar Cah angon, cah angon Penekna blimbing kuwi Lunyu-lunyu penekna Kanggo mbasuh dodotira Dodotira-dodotira Kumitir bedhah ing pinggir Dondomana jlumatana kanggo sebo mengko sore Mumpung padhang rembulane Mumpung jembar kalangane Yo suraka, surak iyo...', 'Bangunlah, bangunlah Tanaman sudah bersemi Telah menghijau seperti pengantin baru Anak gembala, anak gembala Panjatlah pohon belimbing itu Walaupun licin, tetap panjatlah Untuk membasuh pakaianmu Pakaian-pakaianmu Terkoyak pada bagian pinggir Jahitlah dan benahilah untuk waktu sore nanti Selagi bulan masih bersinar terang Selagi masih banyak waktu luang Ayo bersoraklah, sorakan iya...', 'Bagi kehidupan masyarakat Jawa, makna Lir Ilir cukup dalam. Makna lagu Lir Ilir adalah tentang mengisahkan nilai-nilai kehidupan yang harus dipegang teguh oleh manusia.\nPasalnya, dalam kehidupan sehari-hari, lagu ciptaan Sunan Kalijaga ini bisa menjadi pengingat bagi kita untuk senantiasa untuk hidup sederhana, bekerja sama, saling mendukung, dan bersyukur atas segala sesuatu yang telah kita punya atau sesuatu yang kita terima.\n\nContoh, lirik pertama lagu Lir Ilir yang berbunyi \"Lir ilir, lir ilir, tandure wis sumilir\" mengajarkan untuk hidup dengan kesederhanaan dan ketenangan.\n\nSelain itu, suara gending yang menghilang mengandung pesan bahwa segala sesuatu pada akhirnya akan berlalu, jadi kita harus belajar dan kuat untuk merelakan hal tersebut.', 'images/thumb-jateng1.jpg'),
(5, 'Gambang Suling', 'Jawa Tengah', 'jateng-gambang.wav', 'Gambang suling ngumandang suarane\n\nTulat tulit Kepenak unine\n\nUnine mung nrenyuhake\n\nBareng lan kentrung\n\nKetipung suling\n\nSigrak kendangane', 'Gambang suling suaranya nyaring\n\nTulat-tulit, bunyinya enak didengar\n\nBunyinya membuat kita terenyuh\n\nKetika dimainkan bersama ketipung dan suling\n\nBagus suara kendangnya', 'Syair lagu Gambang Suling mengenalkan anak-anak pada alat musik tradisional yaitu seruling.\n\nSelain itu, dalam liriknya juga disebutkan alat musik yang mengiringi bunyi seruling yaitu kentrung, ketipung, dan kendang.\n\nBunyi seruling yang merdu dan mendayu-dayu kerap memberikan makna yang mengharukan.', 'images/thumb-jateng2.jpg'),
(6, 'Jaranan', 'Jawa Tengah', 'jateng-jaranan.wav', 'Jaranan-jaranan, jarane jaran teji\n\nSing numpak ndara bei, sing ngiring para mantri\n\nJek jek nong, jek jek gung, prok prok turut lurung\n\nGedebug krincing gedebug krincing, prok prok gedebug jedher\n\nJaranan-jaranan, jarane jaran kepang\n\nSing numpak klambi abang, mlakune ndhut ndhutan\n\nJek jek nong, jek jek gung, prok prok turut lurung\n\nGedebug krincing gedebug krincing, prok prok gedebug jedher\nJaranan-jaranan, jarane jaran kore\n\nOra ono kendaline, jarane mlaku dewe\n\nJek-jek nong, jek-jek gung, prok prok turut lurung\n\nGedebug krincing gedebug krincing, prok prok gedebug jedher', 'Kuda-kudaan, kuda-kudaan\n\nKudanya kuda teji\n\nYang naik tuan Ngabehi (tuan Kraton), yang mengikuti para abdi\n\nJeg-jeg nong, jeg-jeg gung, prok prok turut lurung\nGedebug krincing gedebug krincing, prok prok gedebug jedher\n\nKuda-kudaan, kuda-kudaan\n\nKudanya kuda kepang\n\nYang naik baju merah, jalannya angguk-anggukan\n\nJeg-jeg nong, jeg-jeg gung, prok prok turut lurung\n\nGedebug krincing gedebug krincing, prok prok gedebug jedher\n\nKuda-kudaan, kuda-kudaan\n\nKudanya kuda kore (jenis kuda perang)\n\nTidak ada kendalinya, kudanya lari sendiri\nJeg-jeg nong, jeg-jeg gung, prok prok turut lurung\n\nGedebug krincing gedebug krincing, prok prok gedebug jedher', 'Bait pertama lagu Jaranan menggambarkan bahwa ada orang yang memiliki kedudukan atau dituakan, sudah sepatutnya orang tersebut lebih dihormati.\n\nPenghargaan dan penghormatan yang diberikan tentu bukan mengarah pada perbuatan untuk merendahkan diri, Adjarian.\n\nNah, kata “merah” pada lirik Jaranan di bait kedua mendeskripsikan pertunjukan kesenian Jaranan yang umumnya menunggangi replika kuda dan berpakaian merah.\n\nKemudian, bait ketiga lagu karya Ki Hadi Supatno ini memiliki makna yang mengandung filosofi hidup.\n\nBait tersebut menceritakan seekor kuda yang akan berlari kencang ketika tidak ada tali di tubuhnya.\nBegitu pula dengan manusia, sebagai manusia kita harus mempu menyelesaikan masalah yang menjadi “pengikat” atau pengekang” dalam diri.', 'images/thumb-jateng3.jpg'),
(7, 'Manuk Dadali', 'Jawa Barat', 'jabar-manuk.wav', 'Mesat ngapung luhur jauh di awang-awang\n\nMébérkeun jangjangna bangun taya karingrang\n\nSukuna ranggoas reujeung pamatukna ngeluk\n\nNgepak mega bari hiberna tarik nyuruwuk\n\nSaha anu bisa nyusul kana tandangna\n\nGandang jeung perténtang taya bandingannana\n\nDipikagimir dipikasérab ku sasama\n\nTaya karempan kasieun lébér wawanénna\n\nManuk dadali manuk panggagahna\n\nPerlambang sakti Indonesia Jaya\n\nManuk dadali pangkakoncarana\n\nResep ngahiji rukun sakabéhna\n\nHirup sauyunan tara pahiri-hiri\n\nSilih pikanyaah teu inggis béla pati\n\nManuk dadali ngandung siloka sinatria\n\nKeur sakumna bangsa di nagara Indonesia', 'Terbang melesat tinggi, jauh di awang-awang\n\nMerentangkan sayapnya, tampil tanpa keraguan\n\nKakinya panjang dan paruhnya melengkung\n\nMenyongsong awan sambil terbang dengan cepat\n\nSiapa yang bisa menyaingi keberaniannya\n\nGagah perkasa tanpa tandingan\n\nDisegani dan disayangi oleh sesama\n\nTanpa ragu tanpa takut, besar nyalinya\n\nBurung garuda, burung paling gagah\n\nLambang sakti Indonesia jaya\n\nBurung garuda, yang paling tersohor\n\nSenang bersatu, rukun semuanya\n\nHidup berhimpun tanpa saling iri\n\nSaling menyayangi, tak sungkan mengorbankan nyawa\n\nBurung garuda adalah lambang kesatriaan\n\nUntuk seluruh bangsa di negara Indonesia', 'Lagu ini mengisahkan tentang kegagahan dan keperkasaan fisik sang garuda. Pencipta lagu ini mendeskripsikan garuda sebagai burung raksasa yang membentangkaan sayap dengan lebar, memiliki kaki yang kuat dan kukuh, serta dianugerahi paruh tajam yang melengkung.\nBurung garuda juga digambarkan memiliki sifat pemberani, lincah, serta disegani dan dihormati oleh makhluk lain. Hal ini tertulis pada bagian \"Dipikagimir dipikasérab ku sasama\".\nSelain menggambarkan fisiknya yang perkasa, dalam lagu ini juga dijelaskan bahwa garuda memiliki sifat yang mencerminkan keluhuran bangsa Indonesia. Garuda disebut memiliki sifat tidak membeda-bedakan, hidup dalam keharmonisan, dan berjiwa kesatria.', 'images/thumb-jabar1.jpg'),
(8, 'Bubuy Bulan', 'Jawa Barat', 'jabar-bubuy.wav', 'Bubuy bulan\nBubuy bulan, sangray béntang\nPanonpoé\nPanonpoé disasaté\nUnggal bulan\nUnggal bulan abdi téang\nUnggal poé\nUnggal poé ogé hadé\nSitu Ciburuy, laukna hésé dipancing\nNyérédét haté ningali ngeplak caina\nTuh, itu saha nu ngalangkung unggal énjing?\nNyérédét haté ningali sorot socana\nBubuy bulan\nBubuy bulan, sangray béntang\nPanonpoé\nPanonpoé disasaté\nUnggal bulan\nUnggal bulan abdi téang\nUnggal poé\nUnggal poé ogé hadé\nSitu Ciburuy, laukna hésé dipancing\nNyérédét haté ningali ngeplak caina\nTuh, itu saha nu ngalangkung unggal énjing?\nNyérédét haté ningali sorot socana\nBubuy bulan\nBubuy bulan, sangray béntang\nPanonpoé\nPanonpoé disasaté\nBubuy bulan\nBubuy bulan', 'Bakar bulan bakar bulan sangray bintang\nMatahari matahari disate\n\nSetiap bulan setiap bulan saya mencari\n\nSetiap hari setiap hari juga baik\n\nTelaga Ciburuy ikannya sulit dipancing\n\nBergetar hati melihat beningnya air\n\nTuh itu siapa yang lewat setiap pagi\n\nBergetar hati melihat sorot matanya\n\nSetiap bulan setiap bulan saya mencari\n\nSetiap hari setiap hari juga baik\n\nTelaga Ciburuy ikannya sulit dipancing\n\nBergetar hati melihat beningnya air\n\nTuh itu siapa yang lewat setiap pagi\n\nBergetar hati melihat sorot matanya\n\nMakna Lagu Bubuy Bulan\nLagu Bubuy Bulan memiliki makna tentang cerita seorang perempuan mengagumi seseorang.\nSuatu hari perempuan tersebut melihat sorot mata yang mirip dengan sorot mata orang yang ia kagumi.', 'Makna \"bubuy bulan\" adalah tentang kesedihan dan kerinduan seorang perempuan terhadap kekasihnya yang pergi. Lagu ini menceritakan rasa sakit hati karena kekasih yang hilang, ditambah rasa sedih ketika melihat seseorang di pagi hari yang sorot matanya mengingatkan pada orang yang dicintai. Selain itu, lagu ini juga memperkenalkan keindahan Situ Ciburuy di Jawa Barat. ', 'images/thumb-jabar2.jpg'),
(9, 'Es Lilin', 'Jawa Barat', 'jabar-eslilin.wav', 'Es lilin mah didorong-dorong\ndibantun mah dibantun ka Sukajadi\nabdi isin ceuceu samar kaduga\nsok sieun mah aduuh henteu ngajadi\n\nEs lilin mah ceuceu buatan Bandung\ndicandakna geuningan ka Cipaganti\nabdi isin jungjunan duh bararingung\nsok inggis mah aduuh henteu ngajadi\n\nItu saha dunungan nu nungtun munding\ndigantelan geuning ku saputangan\nitu saha dunungan ku ginding teuing\nsing horeng mah aduh geuning jungjunan\n\nEs lilin mah ceuceu dikalapaan\nraosna mah geuningan kabina-bina\nabdi alim dunungan paduduaan\nsok sieun mah dibantun kamana-mana\n\nKamana mah dunungan ngaitkeun cingcin\nka kaler mah aduuh katojo bolat\nkamana mah dunungan ngaitkeun pikir\nsakieu mah aduuh panas hatena.', 'Es lilin nyonya, buatan Bandung\n\nDibawanya ternyata ke Cipaganti\n\nSaya malu ya tuan, masih bingung\n\nTakutnya tidak berjodoh\n\n \n\nItu siapa ya tuan, yang menggiring kerbau\n\nDigantungkan gantungan sapu tangan\n\nItu siapa ya tuan, yang berpenampilan keren\n\nTernyata oh ternyata tuan sendiri\n\n \n\nEs lilin dibuat menggunakan kelapa\n\nRasa lezatnya luar biasa\n\nSaya tidak mau berduaan tuan\n\nTakutnya diajak ke mana-mana\n\n \n\nKe mana harus mengaitkan kincir\n\nKe Timur rupanya, menuju bulan\n\nMengapa tuan harus bermuram durja\n\nTak perlu sedih karena cuma sebulan', 'Dilihat dari liriknya, Lagu \"Es Lilin\" memiliki rima yang menyerupai pantung dalam setiap bait. Bagian sampiran dari setiap bait menggunakan beberapa istilah dari es lilin.\n\nIstilah es lilin yang digunakan dalam lagu ini menjadi sebuah kata kiasan atau perumpaan untuk menceritakan makna aslinya.\n\nMakna dari lagu ini adalah seorang perempuan yang merasa malu atau gelisah karena ada seorang laki-laki yang mendekatinya. Beberapa bagian lirik ini juga menunjukan bahwa perempuan tersebut sedang didekati oleh pria terpandang.\n\nLagu \"Es Lilin\" juga ada yang mengartikan sebagai sikap perempuan yang harus lebih berhati-hati dalam memilih pasangan hidup.', 'images/thumb-jabar3.jpg'),
(10, 'Kicir Kicir', 'DKI Jakarta', 'jakarta-kicir.wav', 'Kicir-kicir, ini lagunya\nLagu lama ya Tuan, dari Jakarta\nSaya menyanyi ya Tuan, memang sengaja\nUntuk menghibur, menghibur hati yang duka\n\nBurung dara, burung merpati\nTerbang cepat ya Tuan, tiada tara\nBilalah kita ya Tuan, suka menyanyi\nBadanlah sehat ya Tuan, hati gembira\n\nKicir-kicir, enak lagunya\nDari dulu ya Nona, sampai sekarang\nSaya menyanyi ya Nona, memang sengaja\nUntuk menghibur, menghibur semua orang\n\nBuah mangga enak rasanya\nSi mana lagi ya Tuan, paling ternama\nSiapa saja ya Tuan, rajin bekerja\nPasti menjadi, menjadi warga berguna', 'Kicir-kicir, ini lagunya\nLagu lama ya Tuan, dari Jakarta\nSaya menyanyi ya Tuan, memang sengaja\nUntuk menghibur, menghibur hati yang duka\n\nBurung dara, burung merpati\nTerbang cepat ya Tuan, tiada tara\nBilalah kita ya Tuan, suka menyanyi\nBadanlah sehat ya Tuan, hati gembira\n\nKicir-kicir, enak lagunya\nDari dulu ya Nona, sampai sekarang\nSaya menyanyi ya Nona, memang sengaja\nUntuk menghibur, menghibur semua orang\n\nBuah mangga enak rasanya\nSi mana lagi ya Tuan, paling ternama\nSiapa saja ya Tuan, rajin bekerja\nPasti menjadi, menjadi warga berguna', '\"Hidup bahagia dan berguna.\" Itulah dua pesan yang paling utama dari tembang kebanggan orang Betawi ini. Dari liriknya sendiri, bisa ditangkap bahwa lagu \"Kicir-Kicir\" ingin menghibur mereka yang sedang lara. Hal ini karena perasaan sedih memang memiliki pengaruh kurang baik terhadap fisik.\n\nDari lagu tersebut, \"obat\" untuk membuat hati lebih gembira adalah dengan bernyanyi. Ketika hati senang, badan menjadi sehat dan kita pun gembira.\n\nSelain didendangkan untuk menghibur hati yang berduka, \"Kicir-Kicir\" juga mengingatkan agar setiap orang menjadi individu yang berguna untuk sesama, salah satunya dengan rajin bekerja. Dengan itu, kita setidaknya tidak menjadi beban bagi keluarga maupun masyarakat.', 'images/thumb-jakarta1.jpg'),
(11, 'Jali-Jali', 'DKI Jakarta', 'jakarta-jalijali.wav', 'ini dia si jali-jali\nlagunya enak lagunya enak merdu sekali\ncapek sedikit tidak perduli sayang\nasalkan tuan asalkan tuan senang di hati\npalinglah enak si mangga udang\nhei sayang disayang pohonnya tinggi pohonnya tinggi buahnya jarang\npalinglah enak si orang bujang sayang\nkemana pergi kemana pergi tiada yang m’larang\ndisana gunung disini gunung\nhei sayang disayang ditengah tengah ditengah tengah kembang melati\ndisana bingung disini bingung sayang\nsamalah sama samalah sama menaruh hati\njalilah jali dari cikini sayang\njali-jali dari cikini jalilah jali sampai disini', 'ini dia si jali-jali\nlagunya enak lagunya enak merdu sekali\ncapek sedikit tidak perduli sayang\nasalkan tuan asalkan tuan senang di hati\npalinglah enak si mangga udang\nhei sayang disayang pohonnya tinggi pohonnya tinggi buahnya jarang\npalinglah enak si orang bujang sayang\nkemana pergi kemana pergi tiada yang m’larang\ndisana gunung disini gunung\nhei sayang disayang ditengah tengah ditengah tengah kembang melati\ndisana bingung disini bingung sayang\nsamalah sama samalah sama menaruh hati\njalilah jali dari cikini sayang\njali-jali dari cikini jalilah jali sampai disini', 'Makna lagu \"Jali-jali\" adalah menghibur dan memberikan keceriaan, meskipun dinyanyikan dalam keadaan lelah atau sedih, serta mengandung pesan moral untuk tidak sombong dan menjalani hidup dengan riang. Lagu daerah Betawi yang ceria ini menggunakan lirik berpantun untuk menyampaikan pesan positif tentang kegembiraan dan rasa syukur. ', 'images/thumb-jakarta2.jpg'),
(12, 'Ondel-Ondel', 'DKI Jakarta', 'jakarta-ondel.wav', 'Nyok, kite nonton ondel-ondel Nyok, kite ngarak ondel-ondel Ondel-ondel ade anaknye Anaknye ngigel ter-iteran Mak, bapak ondel-ondel ngibing Ngarak penganten disunatin Goyangnye asyik endut-endutan Nyang ngibing igel-igelan Plak gumbang gumplak plak plak Gendang nyaring ditepak Yang ngiringin nandak Pade surak-surak Tangan iseng ngejailin Kepale anak ondel-ondel Taroin puntungan Rambut kebakaran Anak ondel-ondel jejingkrakkan Kepalenye nyale bekobaran Yang ngarak pade kebingungan Disiramin aer comberan', 'Yuk, kita nonton ondel-ondel Yuk, kita mengiringi ondel-ondel Ondel-ondel ada anaknya Anaknya berputar-putar Ibu, bapak ondel-ondel menari Mengarak pengantin disunat Goyangnya asyik endut-endutan Yang menari igel-igelan (Suara gendang) Gendang nyaring dipukul Yang mengiringi penampilan Sedang bersurak-surak Tangan iseng menggoda Kepala anak ondel-ondel Meletakkan puntungan Rambut kebakaran Anak ondel-ondel lompat-lompat Kepalanya menyala berkobaran Yang mengiringi kebingungan Disiram air comberan', 'Lagu \"Ondel-Ondel\" menceritakan tentang boneka besar yaitu ondel-ondel dan menjadi ikon budaya Betawi.\n\nOndel-ondel merupakan maskot khas masyarakat Betawi berupa boneka besar yang biasanya diarak di acara besar.\n\nNah, diketahui boneka ondel-ondel terdiri dari dua jenis, yaitu laki-laki dan perempuan yang mengenakan baju khas Betawi.\n\nSelain itu, boneka ondel-ondel biasanya diarak untuk memeriahkan pesta rakyat di Jakarta', 'images/thumb-jakarta3.jpg'),
(13, 'Ampar-Ampar Pisang', 'Kalimantan Selatan', 'kalsel-ampar.wav', 'Ampar-ampar Pisang\n\nAmpar-ampar pisang\nPisangku belum masak\nMasak sabigi dihurung bari-bari\nMasak sabigi dihurung bari-bari\n\nMangga lepak mangga lepok\nPatah kayu bengkok\nBengkok dimakan api, apinya canculupan\nBengkok dimakan api, apinya canculupan\n\nNang mana batis kutung dikitip bidawang\nNang mana batis kutung dikitip bidawang', 'Susun-susun pisang\nPisangku belum masak\nMasak sebuah, dipenuhi bari-bari\nMasak sebuah, dipenuhi bari-bari\n\nManggalepak, manggalepok (bunyi dahan/kayu yang patah)\nPatah kayu yang bengkok\nYang bengkok dilalap api, apinya hampir padam\nYang bengkok dilalap api, apinya hampir padam\n\nYang mana kaki buntung, digigit biawak\nYang mana kaki buntung, digigit biawak', 'lagu ini sangat erat dengan kehidupan masyarakat tradisional Kalimantan, terutama suku Dayak yang merupakan masyarakat peramu.\n\nBagian pertama yaitu lirik \"ampar-ampar pisang, pisangku belum masak, masak sabigi dihurung bari-bari, masak sabigi dihurung bari-bari.\"\n\nIni menggambarkan orang yang menyusun pisang yang belum matang. Ada satu biji yang matang tetapi dipenuhi bari-bari atau hewan kecil, bermata merah bata, bertubuh kuning-cokelat, dengan cincin hitam melintang di perut.\n\nPisang ini dimaknai sebagai simbolisasi manusia yang tersusun di muka bumi. Pisang yang masak adalah lambang dari manusia yang baik. Ketika manusia baik, maka akan dikerumuni banyak orang.\n\nPada bait kedua, yaitu \"mangga lepak mangga lepok, patah kayu bengkok, bengkok dimakan api, apinya canculupan, bengkok dimakan api, apinya canculupan\", dimaknai sebagai nasihat yang berarti sesuatu yang bengkong (kejelekan) pasti akan berbunyi keras.\n\nIni dicontohkan seperti anak yang mencuri pisang. Meski mereka berbohong untuk menutupi tindakannya, hal itu pasti akan terungkap.\n\nPada bait terakhir atau ketiga, liriknya adalah \"nang mana batis kutung dikitip bidawang\". Bait ini adalah kesimpulan dari dua bait sebelumnya.\n\nIni menggambarkan pesan agar manusia tidak mencontoh tindakan buruk. Dalam lagu ini digambarkan bahwa hukumannya adalah digigit bidawang atau kura-kura besar.\n\nDemikian tadi penjelasan mengenai lirik lagu Ampar-ampar Pisang, lengkap dengan arti dalam bahasa Indonesia, dan makna yang terkandung di dalamnya.', 'images/thumb-kalsel1.jpg'),
(14, 'Paris Barantai', 'Kalimantan Selatan', 'kalsel-paris.wav', 'Wayah pang sudah\nHari baganti musim\nWayah pang sudah\n\nKotabaru gunungnya bamega\nBamega umbak manampur di sala karang\nUmbak manampur di sala karang\n\nBatamu Lawanlah adinda\nAdinda iman di dada rasa malayang\nIman di dada rasa malayang\n\nPisang silat tanamlah babaris\nBabaris tabang pang bamban kuhalangakan\nTabang pang bamban kuhalangakan\n\nBahalat gununglah babaris\nBabaris hatiku dandam kusalangakan\nHatiku dandam kusalangakan\n\nBurung binti batiti di batang\nDi batang si batang buluh kuning manggading\nSi batang buluh kuning manggading\n\nMalam tadi bamimpilah datang\nRasa datang rasa bapaluk lawan si ading\nRasa bapaluk lawan si ading', 'Sudah saatnya Hari berganti musim Sudah saatnya\n\nKotabaru gunungnya bermega (berawan) Bermega, ombak memecah di sela karang Ombak memecah di sela karang\n\nBertemu denganlah adinda Adinda, iman di dada rasa melayang Iman di dada rasa melayang\n\nPisang silat ditanam berbaris Berbaris, tebanglah pohon bamban untuk kuhalangi Tebanglah pohon bamban untuk kuhalangi\n\nTerhalang gununglah berbaris Berbaris, hatiku rindu yang kutanggungkan Hatiku rindu yang kutanggungkan\n\nBurung binti meniti di batang Di batang, si batang bambu kuning yang gading Si batang bambu kuning yang gading\n\nMalam tadi bermimpilah (kau) datang Serasa datang, serasa berpeluk dengan adinda Serasa berpeluk dengan adinda', 'Lagu \"Paris Barantai\" menceritakan tentang kerinduan pada kekasih yang terpisah jarak, di mana kata \"Paris\" di sini bukan merujuk pada kota di Prancis, melainkan frasa \"berpisah sementara karena berlayar\" dalam bahasa Banjar. Lirik lagu ini menggambarkan keindahan alam Kalimantan, harapan, dan mimpi bertemu kekasih, seperti \'gunung bamega\' (gunung berawan) dan \'umbak manampur di sala karang\' (ombak menghantam karang). ', 'images/thumb-kalsel2.jpg'),
(15, 'Sasirangan', 'Kalimantan Selatan', 'kalsel-sasirangan.wav', 'Babaju adat raja wan ratu bahari\nWayah karajaan banjar\nBagambar naga balimbur gigi haruan\nOmbak sinapur karang\n\nJaga wan lastarikan\nKain paninggalan warisan asli\nBudaya banjar\n\n\nBasasirangan\nUmay himungnya\nMamakai kain kabanggaan Banjar\nBasasirangan\nUmay himungnya\nMamakai kain adat khas Banjar\n\n\nKain pamintaan gasan batatambaan\nUrang nang panggaringan\nDiulah jadi laung kakamban wan tapih\nBumin bungas wan langkar banar\n\nJaga wan lastarikan\nKain paninggalan warisan asli\nBudaya banjar\n\n\nBasasirangan\nUmay himungnya\nMamakai kain kabanggaan Banjar\nBasasirangan\nUmay himungnya\n\nMamakai kain adat khas Banjar\n\nJaga wan lastarikan\nKain paninggalan\nWarisan asli\nBudaya banjar\n\n\nBasasirangan\nUmay himungnya\nMamakai kain kabanggaan Banjar\nBasasirangan\nUmay himungnya\nMamakai kain adat khas Banjar\n\nBasasirangan\nUmay himungnya\nMamakai kain kabanggaan Banjar\nBasasirangan\nUmay himungnya\nMamakai kain adat khas Banjar\n\nBasasirangan\nUmay himungnya\nMamakai kain kabanggaan Banjar\nBasasirangan\nUmay himungnya\nMamakai kain adat khas Banjar\n\n\nBasasirangan\nUmay himungnya', 'Berbaju adat raja dan ratu zaman dahulu Di waktu kerajaan Banjar Bergambar naga balimbur, gigi haruan (motif gigi ikan gabus) Ombak sinapur karang (motif ombak menerjang karang)\n\nJaga dan lestarikan Kain peninggalan warisan asli Budaya Banjar\n\nBersasirangan (Memakai Sasirangan) Aduh senangnya/bahagianya Memakai kain kebanggaan Banjar Bersasirangan Aduh senangnya/bahagianya Memakai kain adat khas Banjar\n\nKain permintaan untuk pengobatan Orang yang sakit-sakitan Dibuat jadi laung (ikat kepala), kakamban (selendang), dan tapih (sarung) Penampilannya cantik dan indah sekali\n\nJaga dan lestarikan Kain peninggalan Warisan asli Budaya Banjar\n\nBersasirangan Aduh senangnya Memakai kain kebanggaan Banjar Bersasirangan Aduh senangnya Memakai kain adat khas Banjar', 'Sasirangan adalah kain tradisional dari Kalimantan Selatan yang motifnya dibuat dengan teknik jelujur atau \"menyirang\" yang berasal dari kata \"sirang\" dalam bahasa Banjar. Awalnya, kain ini memiliki fungsi magis untuk menyembuhkan penyakit dan mengusir roh jahat. Saat ini, sasirangan juga digunakan untuk keperluan praktis sehari-hari seperti sebagai laung (ikat kepala) dan kerudung. ', 'images/thumb-kalsel3.jpg'),
(16, 'Rasa Sayange', 'Maluku', 'maluku-rasa.wav', 'Rasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\n\nDi sana gunung di sini gunung\nTengah tengah bunga melati\nDi sana bingung di sini bingung\nDua dua teman sejati\n\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\n\nJalan jalan ke Surabaya\nJangan lupa membeli pita\nJangan suka memandang saya\nNanti bisa sakit mata\n\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\n\nKalau ada sumur di ladang\nBoleh kita menumpang mandi\nKalau ada umurku panjang\nBoleh kita berjumpa lagi\n\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange', 'Rasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\n\nDi sana gunung di sini gunung\nTengah tengah bunga melati\nDi sana bingung di sini bingung\nDua dua teman sejati\n\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\n\nJalan jalan ke Surabaya\nJangan lupa membeli pita\nJangan suka memandang saya\nNanti bisa sakit mata\n\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\n\nKalau ada sumur di ladang\nBoleh kita menumpang mandi\nKalau ada umurku panjang\nBoleh kita berjumpa lagi\n\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange\nRasa sayange rasa sayang sayange\nLihat nona dari jauh rasa sayang sayange', 'Makna dari lirik lagu ini bercerita soal para orang tua di Maluku yang memberikan kasih sayang terhadap lingkungan dan cara bersosialisasi dengan masyarakat sekitar. ', 'images/thumb-maluku1.jpg'),
(17, 'Ayo Mama', 'Maluku', 'maluku-ayomama.wav', 'Ayo mama jangan mama marah beta\nDia cuma cuma cuma pegang beta\nAyo mama jangan mama marah beta\nLah orang muda punya biasa\nAyam hitam telurnya putih\nMencari makan di pinggir kali\nSinyo hitam giginya putih\nKalau ketawa manis sekali\nAyo mama jangan mama marah beta\nDia cuma cuma cuma pegang beta\nAyo mama jangan mama marah beta\nLah orang muda punya biasa\nAyam hitam telurnya putih\nMencari makan di pinggir kali\nSinyo hitam giginya putih\nKalau ketawa manis sekali\nAyo mama jangan mama marah beta\nDia cuma cuma cuma pegang beta\nAyo mama jangan mama marah beta\nLah orang muda punya biasa\nAyam hitam telurnya putih\nMencari makan di pinggir kali\nSinyo hitam giginya putih\nKalau ketawa manis sekali\nAyo mama jangan mama marah beta\nDia cuma cuma cuma pegang beta\nAyo mama jangan mama marah beta\nLah orang muda punya biasa\nAyam hitam telurnya putih\nMencari makan di pinggir kali\nSinyo hitam giginya putih\nKalau ketawa manis sekali', 'Ayam hitam, telurnya putih\n\nMencari makan di tepi sungai\n\nSinyo hitam, giginya putih\n\nSangat manis saat tertawa\n\nAyo mama, janganlah marah padaku\n\nDia hanya menciumku\n\nAyo mama, janganlah marah padaku\n\nPemuda memiliki kebiasaan mereka sendiri\n\nLembe-lembe makan ketupat\n\nSaudagar lajang berendam di sungai mangir\n\nMambu reweh mau bersumpah\n\nNamun terlalu manis untuk diingat oleh sang bujangan\n\nAyo mama, janganlah marah padaku\n\nDia hanya menciumku\n\nAyo mama, janganlah marah padaku\n\nPemuda memiliki kebiasaan mereka sendiri', 'Makna lagu \"Ayo Mama\" adalah tentang percakapan seorang anak remaja dengan ibunya di mana si anak mencoba membujuk ibunya agar tidak marah karena ketahuan berpacaran, sambil menjelaskan bahwa mereka hanya berpegangan tangan dan itu adalah hal yang biasa dilakukan anak muda. Lagu daerah asal Ambon ini, dengan irama ceria, juga menyampaikan pesan untuk bergembira bersama serta menghormati orang tua meskipun ada perbedaan pandangan. ', 'images/thumb-maluku2.jpg'),
(18, 'Poco Poco', 'Maluku', 'maluku-poco.wav', 'Balenggang pata pata\nNgana pegoyang pica pica\nNgana pebody poco poco\nCuma ngana yang kita cinta\nCuma ngana yang kita sayang\nCuma ngana suka bikin pusing\nBalenggang pata pata\nNgana pegoyang pica pica\nNgana pebody poco poco\nCuma ngana yang kita cinta\ncuma ngana yang kita sayang\ncuma ngana suka bikin pusing\nNgana bilang kita na sayang\nRasa hati ini malayang jauh dija dija\nBiar ngana kita pebayang\nBiar na bikin layang layang\nCuma ngana yang kita sayang', 'Berjalan melenggang patah-patah Goyanganmu heboh (lincah) sekali Badanmu montok (berisi) Cuma kamu yang saya cinta Cuma kamu yang saya sayang Cuma kamu yang suka bikin pusing\n\nBerjalan melenggang patah-patah Goyanganmu heboh (lincah) sekali Badanmu montok (berisi) Cuma kamu yang saya cinta Cuma kamu yang saya sayang Cuma kamu yang suka bikin pusing\n\nKamu bilang saya tidak sayang Rasa hati ini melayang jauh entah ke mana Biarpun kamu jadi bayang-bayangku Biarpun kamu jadikan (aku) layang-layang Cuma kamu yang saya sayang', ' konteks lagu dan tarian Poco-Poco dari Maluku, maknanya adalah tentang kegembiraan, semangat, kebersamaan, dan kebahagiaan karena cinta. Kata ini juga bisa diartikan sebagai \"menggemaskan\" dalam bahasa Ternate, mengacu pada gerakan tarian atau sifat seseorang. ', 'images/thumb-maluku3.jpg'),
(19, 'Yamko Rambe Yamko', 'Papua', 'papua-yamko.wav', 'Hee yamko rambe yamko aronawa kombe\n\nHee yamko rambe yamko aronawa kombe\n\nTeemi nokibe kubano ko bombe ko\n\nYumano bungo awe ade\n\nTeemi nokibe kubano ko bombe ko\n\nYumano bungo awe ade\n\nHongke hongke hongke riro\n\nHongke jombe jombe riro\n\nHongke hongke hongke riro\n\nHongke jombe jombe riro', 'Hai jalan yang dicari sayang perjanjian\n\nHai jalan yang dicari sayang perjanjian\n\nSungguh pembunuhan di dalam negeri\n\nSungguh pembunuhan di dalam negeri sebagai bunga\n\nBunga bangsa, bunga bangsa, bunga bertaburan, di taman pahlawan\n\nBunga bangsa, bunga bangsa, bunga bertumbuh, di taman pahlawan\n\nBunga bangsa, bunga bangsa, bunga bertaburan\n\nBunga bangsa, bunga bangsa, bunga bertumbuh', 'Lagu Yamko Rambe Yamko memiliki makna tersirat. Yamko Rambe Yamko mengandung makna yang sangat mendalam dan memiliki nilai-nilai moral di dalamnya. Walaupun lagu Yamko Rambe Yamko memiliki tempo yang cepat dan terkesan riang, lagu ini memiliki kisah yang cukup kelam. Lagu ini mengisahkan tentang pertikaian yang sedang terjadi di dalam negeri.\n\nLagu ini diceritakan dalam sudut padat sang pelantun yang ingin menjadi seorang bunga bangsa. Bunga bangsa di sini, memiliki arti sebagai pahlawan. Sang pelantun ingin menjadi pahlawan yang siap berkorban sampai mati demi mempertahankan negara Indonesia dari serangan penjajah sebelum Indonesia merdeka pada tahun 1945.\n\nPada lirik lagu bagian hongke hongke riro hongke hongke jombe jombe riro, memiliki arti bahwa banyak sekali pahlawan bangsa yang saat itu gugur dalam membela bangsa melawan penjajah, dan banyak bunga yang bertaburan pada makam para pahlawan.\n\nLagu ini bertujuan untuk menghidupkan suasana yang muram, menambah semangat, dan menjadi pengiring pada acara-acara adat. Lagu ini memiliki nilai moral yang baik, yaitu, masyarakat janganlah berbuat jahat dan mari saling menghormati orang tua.', 'images/thumb-papua1.jpg'),
(20, 'Apuse', 'Papua', 'papua-apuse.wav', 'Apuse kokon dao\nYarabe soren doreri\nWuf lenso bani nema beki pase\n\nApuse kokon dao\nYarabe soren doreri\nWuf lenso bani nema beki pase\n\nArafa Bye aswara war\nArafa Bye aswara war\n\nApuse kokon dao\nYarabe soren doreri\nWuf lenso bani nema beki pase\n\nArafa Bye aswara war\nArafa Bye aswara war\n\nApuse kokon dao\nYarabe soren doreri\nWuf lenso bani nema beki pase\n\nArafa Bye aswara war\nArafa Bye aswara war', 'Kakek-nenek aku mau\nPergi ke negeri seberang Teluk Doreri\nPegang sapu tangan dan melambaikan tangan\n\nKakek-nenek aku mau\nPergi ke negeri seberang Teluk Doreri\nPegang sapu tangan dan melambaikan tangan\n\nKasihan aku, selamat jalan cucuku\nKasihan aku, selamat jalan cucuku\n\nKakek-nenek aku mau\nPergi ke negeri seberang Teluk Doreri\nPegang sapu tangan dan melambaikan tangan\n\nKakek-nenek aku mau\nPergi ke negeri seberang Teluk Doreri\nPegang sapu tangan dan melambaikan tangan\n\nKasihan aku, selamat jalan cucuku\nKasihan aku, selamat jalan cucuku', 'Lagu Apuse mengisahkan tentang sorang cucu yang ingin pergi merantau.\nKemudian, cucu tersebut berpamitan dengan kakek neneknya.\n\nLebih tepatnya sang cucu ingin merantau ke Teluk Doreri di daerah Manokwari.\n\nMelalui lagu ini kita merasakan beratnya perasaan ditinggal oleh orang tersayang.', 'images/thumb-papua2.jpg'),
(21, 'Sajojo', 'Papua', 'papua-sajojo.wav', 'Sajojo, sajojo\nYumanampo misa papa\nSamuna muna muna keke\nSamuna muna muna keke\n\nSajojo, sajojo\nYumanampo misa papa\nSamuna muna muna keke\nSamuna muna muna keke\n\nKuserai, kusaserai rai rai rai rai\nKuserai, kusaserai rai rai rai rai\n\nInamgo mikim ye\nPia sore, piasa sore ye ye\nInamgo mikim ye\nPia sore, piasa sore ye ya\n\n', 'Saya Jojo saya Jojo\nSaya minta izin\nMembawa putri Anda Keke\nMembawa putri Anda Keke\n\nSaya Jojo saya Jojo\nSaya minta izin\nMembawa putri Anda Keke\nMembawa putri Anda Keke\n\nSaya akan memberikan seluruh hidupku\n\nKami berencana pergi keluar\nBeri kami kesempatan\nKami akan pulang sore hari\nYa, sore hari\n\nKami berencana pergi keluar\nBeri kami kesempatan\nKami akan pulang sore hari\nYa, sore hari\n\nSaya Jojo saya Jojo\nSaya minta izin\nMembawa putri Anda Keke\nMembawa putri Anda Keke\n\nAku akan memberikan seluruh hidupku\n\nKami berencana pergi keluar\nBeri kami kesempatan\nKami akan pulang sore hari\nYa, sore hari', 'Seperti dijelaskan di atas, makna lagu Sajojo bercerita tentang seorang laki-laki bernama Jojo yang ingin mengajak si gadis kembang desa untuk jalan-jalan di sore hari.\n\nLelaki itu pun meminta izin kepada orang tua si gadis dan berharap diberi kesempatan untuk membawa putrinya.\n\nSi gadis kembang desa sendiri adalah anak yang cantik yang disayangi oleh keluarganya. Karena itulah banyak pria yang jatuh hati kepadanya.', 'images/thumb-papua3.jpg'),
(22, 'Kampuang Nan Jauh di Mato', 'Sumatra Barat', 'sumbar-kampuang.wav', 'Kampuang nan jauah di mato\nGunuang sansai ba kuliliang\nDen takana jo kawan-kawan lamo\nSangkek basuliang-suliang\n\nPanduduaknyo nan elok\nNan suko bagotong royong\nSakik sanang samo-samo di raso\nDen takana jo kampuang\n\nTakana jo kampuang\nInduak, Ayah, Adiak sadonyo\nRaso maimbau-imbau Den pulang\nDen takana jo kampuang', 'Kampung halaman yang jauh di mata\nGunung banyak sekelilingnya\n\'Ku terkenang pada kawan-kawan lama\nSaat bersuling-suling\n\nPenduduknya yang baik\nYang suka bergotong-royong\nKalau susah sama-sama dirasa\nAku teringat pada kampung\n\nTerkenang pada kampung halaman\nIbu, ayah, adik, semuanya\nSerasa memanggil aku pulang\nAku teringat pada kampung', 'Homesick, itulah inti dari tembang asal Ranah Minang yang satu ini. Ada sumber yang menyebutkan bahwa \"Kampuang Nan Jauh di Mato\" ditulis Oslan Husein, tetapi sumber lain mengatakan A. Minos. Terlepas dari itu, lagu ini erat hubungannya dengan tradisi suku Minangkabau yang sering merantau ke negeri orang untuk mengadu nasib.\n\nTak jarang, semasa di perantauan, kita tiba-tiba teringat dengan kampung halaman yang jauh di sana. Muncul rasa rindu dengan keluarga dan tetangga, begitu juga dengan memori sewaktu bermain bersama kawan-kawan lama.\n\nPerasaan itulah yang digambarkan oleh lagu \"Kampuang Nan Jauh di Mato\". Karena mengisahkan kerinduan di perantauan, bisa dikatakan lagu daerah ini merupakan curahan hati para anak rantau.', 'images/thumb-sumbar1.jpg'),
(23, 'Ayam Den Lapeh', 'Sumatra Barat', 'sumbar-ayamden.wav', 'Luruihlah jalan Payakumbuah\n\nBabelok jalan kayujati\n\nDimahati indak karusuah\n\nAyam den lapeh\n\n \n\nAi ai ayam den lapeh\n\nMandaki jalan Pandai Sikek\n\nManurun jalan ka Biaro\n\nDima hati indak ka maupek\n\nAyam den lapeh\n\nAi ai ayam den lapeh\n\n \n\nSikua capang sikua capeh\n\nSaikua tabang saikua lapeh\n\nLapehlah juo nan ka rimbo\n\nOi lah malang juo\n\n \n\nPagaruyuang Batusangka\n\nTampek bajalan urang Baso\n\nDuduak tamanuang tiok sabanta\n\nAyam den lapeh\n\nAi ai ayam den lapeh\n\n \n\nSikua capang sikua capeh\n\nSaikua tabang saikua lapeh\n\nLapehlah juo nan ka rimbo\n\nOi lah malang juo\n\n \n\nPagaruyuang Batusangka\n\nTampek bajalan urang Baso\n\nDuduak tamanuang tiok sabanta\n\nAyam den lapeh\n\n \n\nAi ai ayam den lapeh\n\nSikua capang sikua capeh\n\nSaikua tabang saikua lapeh\n\nLapehlah juo nan ka rimbo\n\nOi lah malang juo\n\n \n\nPagaruyuang Batusangka\n\nTampek bajalan urang Baso\n\nDuduak tamanuang tiok sabanta\n\nAyam den lapeh\n\nAi ai ayam den lapeh\n\nAi ai ayam den lapeh', 'Lurus jalan ke Payakumbuh\nBerbelok jalan kayu jati\nBagaimana hati tidak akan rusuh\nAyamku lepas ai ai\nAyamku lepas\n\nMendaki jalan Pandai Sikek\nBersimpang jalan ke Biaro\nBagaimana hati tidak akan mengupat\nAku terkecoh ai ai\nAyamku lepas\n\nSeekor capang seekor capeh\nseekor terbang seekor lepas\nLepaslah dia yang ke rimba\nOh malangnya juga\n\nPagaruyung Batusangkar\nTempat berjalan orang Baso\nDuduk bermenung setiap saat\nOh teringat juga ai ai\nAyamku lepas', 'Ayam dalam lagu ini berarti kekasih hati. Sesuai dengan judulnya, maka Ayam Den Lapeh adalah lagu yang memiliki arti kekasihku pergi. Lagu ini tentang kesedihan mendalam akibat kehilangan kekasih. \n\nSedangkan, rimbo dalam liriknya berarti orang lain. Jadi, Ayam Den Lapeh menggambarkan kekasih hati yang pergi karena jatuh hati pada perempuan lain.', 'images/thumb-sumbar2.jpg'),
(24, 'Bareh Solok', 'Sumatra Barat', 'sumbar-bareh.wav', 'Bareh Solok tanak di dandang\n\nDipagatok ulam pario\n\nBunyi kulek cando badendang\n\nDek ditingkah (hmm) si samba lado\n\nUrang Sumpu jalan barampek\n\nDi Singkarak singgah dahulu\n\nBareh baru makan jo pangek\n\nIndak nampak (hmm) mintuo lalu\n\nBareh Solok bareh tanamo\n\nBareh Solok lamak rasonyo\n\nBareh Solok bareh tanamo\n\nBareh Solok lamak rasonyo', 'Beras Solok, di tanak di dandang (periuk Besar)\n\nDi lalap dengan peria (sayuran berasa agak pahit)\n\nBunyi ketika mengunyah seperti berdendang\n\nDitambah dengan sambal cabe\n\nOrang Sumpu jalan berempat\n\nDi Singkarak singgah sebentar\n\nBeras baru, makan dengan Pangek (kuliner dari Minangkabau)\n\nTak terlihat mertua lewat\n\nBeras Solok, Beras ternama\n\nBeras Solok enak rasanya\n\nBeras Solok beras ternama\n\nBeras Solok enak rasanya', 'Lagu \"Bareh Solok\" bercerita tentang kelezatan beras dari daerah Solok, Sumatera Barat, yang begitu enak sehingga membuat orang ketagihan, terutama saat disantap dengan lauk seperti sambalado. Lagu ini diciptakan oleh Nuskan Syarief dan dipopulerkan oleh penyanyi Elly Kasim. Makna dari lagu ini adalah untuk mempromosikan beras Solok sebagai komoditas istimewa yang memiliki cita rasa khas dan berkualitas tinggi. ', 'images/thumb-sumbar3.jpg'),
(25, 'Kadal Nongak', 'Nusa Tenggara Barat', 'ntb-kadalnongak.wav', 'Kadal nongak leq kesambiq\nBenang kataq setakilan\nAduh dende\nMun cempake siq kembang sandat\nSaq sengake jari sahabat\n\nTe ajah onyak ndek ne matiq\nNane rasaq kejarian\nAduh dende\nMun cempake siq kembang sandat\nSaq sengake jari sahabat', 'Kadal nengok di pohon besar\nBenang mentah sekepalan\nAduh Sayang\nBunga cempaka jadi bunga sandat\nYang paling tua jadi sahabat\n\nDiajar hati hati  tidak dituruti\nSekarang rasakan akibatnya\nAduh Sayang\nBunga cempaka jadi bunga sandat\nYang paling tua jadi sahabat', 'Lagu ini bercerita tentang seorang anak gadis yang tidak mendengarkan kata-kata kakaknya. Karena itu, dia pun menerima ganjaran. Sang ibu yang melihat hal tersebut dilanda rasa iba, lalu menasehati sang buah hati dengan cara menyairkannya. \n\nKini, Kadal Nongak menjadi lagu yang kerap dijadikan sebagai sarana didikan terhadap anak-anak di bangku sekolah dasar. ', 'images/thumb-ntb-kadalnongak.jpg'),
(26, 'Poto Tano', 'Nusa Tenggara Barat', 'ntb-pototano.wav', 'Poto Tano lawang desa\nPalabu tana samawa\nNo sendi ya tu kalupa\nGili ode mara intan\nKasear nonda baroba\nTulang jangi tu balayar\n\n\nBelo tampar somo umak\nSenap angin batarepa\nSajan ngasi ate notang\nMe potanang no ku totang\nSia tu ka bilin desa\nLangan lo layar let rea\n\n\nSendi sate tu sangaro\nBentan gama we tanenang\nSalam doa ku ko bulan\nLeng palabu poto tano\nKu nokong ke ai mata\nKu tari kanatang sia\n\n\nSabar gama we andi e..\nNa gier iman leng ate\nMares pakarap kulete..\nLamen yanan si bagian\nMana pamalat let rea\nSadi jangi gayong kita\n\n\nBelo tampar somo umak\nSenap angin batarepa\nSajan ngasi ate notang\nMe potanang no ku totang\nSia tu ka bilin desa\nLangan lo layar let rea\n\nSendi sate tu sangaro\nBentan gama we tanenang\nSalam doa ku ko bulan\nLeng palabu poto tano\nKu nokong ke ai mata\nKu tari kanatang sia\nLeng palabu poto tano\nKu nokong ke ai mata\nKu tari kanatang sia', 'Poto Tano pintunya desa Pelabuhan Tanah Sumbawa Tak sedikitpun akan terlupakan Pulau kecil tampak bak intan Tersebar dan tak berubah Menatap nasib kita yang berlayar Pantai yang memanjang menadah ombak Sejuk angin menerpa\n\nSemakin merana hati yang merindu Bagaimana mungkin aku tak rindu Engkau pergi tinggalkan Sumbawa Berjalan mengarungi laut yang luas Ingin rasanya ku meminta Bawalah wahai burung Salam dan doaku untuk bulan (kekasih) Di pelabuhan Poto Tano\n\nAku datang dengan air mata Ku menunggu kedatanganmu Bersabarlah wahai adinda Jangan goyah iman di hatimu Semoga harapan selalu ku titih Kalau memang itulah (engkaulah) separuhku Walau berbatas laut yang luas Pastikan nasib mempersatukan kita', 'Makna \"Poto Tano\" adalah pelabuhan tanah yang merupakan gerbang keindahan Sumbawa dan titik pertemuan budaya antara Sumbawa dan Lombok. Kata \"Poto\" berarti pelabuhan dan \"Tano\" berarti tanah dalam bahasa lokal. Kawasan ini memiliki sejarah panjang sebagai pusat perdagangan dan pertukaran budaya, serta dikenal dengan keindahan alamnya dan kehidupan masyarakat nelayan yang tradisional. ', 'images/thumb-ntb-pototano.jpg'),
(27, 'Jari Roro', 'Nusa Tenggara Barat', 'ntb-jariroro.wav', 'Montok Mesaq Reduk Nanges…\nPedi Paranamu Ate\nNanta We Nasib We Jangi Dita Tu ngepak..\nTungepak Mara adal\n\nTeri Adal Langan Gasal…\nNgarereng Lo Bide Jawa\nIntan Gantuna Kugama Gama\nGama  We Intan\nWe Intan Gantuna\n\n\nCece We Parana Kaku\nMara Bangka Ning Tenga Let\nBilu We Antat Ning Bagian …\nAntat Ning Antat Ning  Bilu We Bagian\n\nWe Sia Bolang Ke No G...antuna\nAku Pili Melasakan\nNo Gampang Na We No gampangNa Jari Roro… Na Jari Roro\n\nAku Tau Ning TengaTan Rara\nKupasampar Melasakan\nKupia Ipi We Kupia Ipi Salingong\nIpi Salingong… Ipi Salingong', 'Duduk menyendiri sambil menangis\nKasihan badan mu hati\nKasihan nasib, janji kita\nDuduk seperti embun\n\nJatuh embun lewat delima\nBerbaris di Alaskan tikar jawa\nIntan mubasir\nSemoga intan\nIntan mubasir\n\nKasihan badanku\nSeperti perahu di tengah laut\nBelok diantar oleh nasib\nDi antar-di antar ke baian\n\nKamu buang tidak menyesal\nAku pilih kasihan\nTidak susah, tidak susah jadi sampah\n\nAku orang di tengah miskin\nBeralaskan sengsara\nAku jadikan mimpi dalam kesepian\nMimpi kesepian\nMimpi kesepian\n', 'Menggambarkan kesedihan mendalam atau kekecewaan dalam hubungan asmara yang kandas di tengah jalan.', 'images/thumb-ntb-jariroro.jpg');

